               facts=[("ప్లాట్‌ఫామ్", "Android, iPhone తర్వాత"), ("ధర", "ఇప్పుడు ఉచితం"), ("భాష", "యాప్ ఇంగ్లీష్‌లో ఉంది"), ("తయారీ", "Dhruv Gupta, భారతదేశం")],
